const promoView=document.querySelector('#promo');
promoView.innerHTML='<div class="view-head"><div><h2>Promosi dan voucher</h2><p>Atur potongan harga yang divalidasi langsung oleh server.</p></div><button class="primary" id="addPromotion">＋ Tambah voucher</button></div><section class="panel table-wrap"><table class="table"><thead><tr><th>Kode</th><th>Promosi</th><th>Diskon</th><th>Minimum</th><th>Masa berlaku</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="promotionRows"></tbody></table><div class="empty" id="promotionEmpty" hidden>Belum ada voucher.</div></section>';
const promotionDialog=document.createElement('dialog');promotionDialog.className='modal';promotionDialog.innerHTML='<form class="modal-inner" id="promotionForm"><div class="modal-head"><h2 id="promotionTitle">Tambah voucher</h2><button class="close" type="button" id="promotionClose" aria-label="Tutup">×</button></div><input id="promotionId" type="hidden"><div class="form-grid"><div class="field"><label for="promotionCode">Kode voucher</label><input id="promotionCode" required maxlength="24" placeholder="HEMAT10"></div><div class="field"><label for="promotionName">Nama promosi</label><input id="promotionName" required maxlength="80"></div><div class="field"><label for="promotionType">Jenis diskon</label><select id="promotionType"><option value="percent">Persentase</option><option value="fixed">Nominal rupiah</option></select></div><div class="field"><label for="promotionValue">Nilai diskon</label><input id="promotionValue" type="number" min="1" required></div><div class="field"><label for="promotionMaximum">Maksimum diskon</label><input id="promotionMaximum" type="number" min="0" placeholder="Kosong = tanpa batas"></div><div class="field"><label for="promotionMinimum">Minimum belanja</label><input id="promotionMinimum" type="number" min="0" value="0" required></div><div class="field"><label for="promotionStart">Mulai</label><input id="promotionStart" type="datetime-local"></div><div class="field"><label for="promotionEnd">Berakhir</label><input id="promotionEnd" type="datetime-local"></div><div class="field wide"><label><input id="promotionActive" type="checkbox" checked> Voucher aktif</label></div></div><div class="form-actions"><button class="secondary" id="promotionCancel" type="button">Batal</button><button class="primary" type="submit">Simpan voucher</button></div></form>';
document.body.append(promotionDialog);
const promoStyle=document.createElement('style');promoStyle.textContent='.promo-actions{display:flex;gap:7px}.promo-code{font-weight:800;letter-spacing:.05em}.promo-date{font-size:.75rem;color:var(--muted);white-space:nowrap}.danger-btn{border-color:#d7a795;color:#9b5430}';document.head.append(promoStyle);
let promotions=[];
const localDate=value=>{if(!value)return'';const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)};
function promotionDiscountLabel(item){return item.type==='percent'?`${item.value}%${item.maxDiscount!=null?` · maks ${rupiah(item.maxDiscount)}`:''}`:rupiah(item.value)}
function promotionPeriod(item){if(!item.startsAt&&!item.expiresAt)return'Tanpa batas waktu';return`${item.startsAt?new Date(item.startsAt).toLocaleDateString('id-ID'):'Sekarang'} – ${item.expiresAt?new Date(item.expiresAt).toLocaleDateString('id-ID'):'Seterusnya'}`}
function renderPromotions(){const rows=document.querySelector('#promotionRows');rows.innerHTML=promotions.map(item=>`<tr><td class="promo-code">${escapeHtml(item.code)}</td><td><strong>${escapeHtml(item.name)}</strong></td><td>${escapeHtml(promotionDiscountLabel(item))}</td><td>${rupiah(item.minPurchase)}</td><td class="promo-date">${escapeHtml(promotionPeriod(item))}</td><td><span class="status ${item.isActive?'':'low'}">${item.isActive?'Aktif':'Nonaktif'}</span></td><td><div class="promo-actions"><button class="icon-btn promo-edit" data-id="${item.id}">Edit</button><button class="icon-btn danger-btn promo-delete" data-id="${item.id}">Hapus</button></div></td></tr>`).join('');document.querySelector('#promotionEmpty').hidden=promotions.length>0;document.querySelectorAll('.promo-edit').forEach(button=>button.addEventListener('click',()=>openPromotion(Number(button.dataset.id))));document.querySelectorAll('.promo-delete').forEach(button=>button.addEventListener('click',()=>deletePromotion(Number(button.dataset.id))))}
async function loadPromotions(){try{const data=await api('/api/promotions');promotions=data.promotions||[];renderPromotions()}catch(error){toast(error.message)}}
function openPromotion(id){const item=promotions.find(entry=>entry.id===id);document.querySelector('#promotionTitle').textContent=item?'Edit voucher':'Tambah voucher';document.querySelector('#promotionId').value=item?.id||'';document.querySelector('#promotionCode').value=item?.code||'';document.querySelector('#promotionName').value=item?.name||'';document.querySelector('#promotionType').value=item?.type||'percent';document.querySelector('#promotionValue').value=item?.value||10;document.querySelector('#promotionMaximum').value=item?.maxDiscount??'';document.querySelector('#promotionMinimum').value=item?.minPurchase||0;document.querySelector('#promotionStart').value=localDate(item?.startsAt);document.querySelector('#promotionEnd').value=localDate(item?.expiresAt);document.querySelector('#promotionActive').checked=item?Boolean(item.isActive):true;promotionDialog.showModal()}
async function deletePromotion(id){const item=promotions.find(entry=>entry.id===id);if(!item||!confirm(`Hapus voucher ${item.code}?`))return;try{await api(`/api/promotions/${id}`,{method:'DELETE'});toast('Voucher berhasil dihapus');await loadPromotions()}catch(error){toast(error.message)}}
document.querySelector('#addPromotion').addEventListener('click',()=>openPromotion());document.querySelector('#promotionClose').addEventListener('click',()=>promotionDialog.close());document.querySelector('#promotionCancel').addEventListener('click',()=>promotionDialog.close());document.querySelector('.menu button[data-view="promo"]').addEventListener('click',loadPromotions);
document.querySelector('#promotionForm').addEventListener('submit',async event=>{event.preventDefault();const id=document.querySelector('#promotionId').value,button=event.submitter,start=document.querySelector('#promotionStart').value,end=document.querySelector('#promotionEnd').value,payload={code:document.querySelector('#promotionCode').value,name:document.querySelector('#promotionName').value,type:document.querySelector('#promotionType').value,value:Number(document.querySelector('#promotionValue').value),maxDiscount:document.querySelector('#promotionMaximum').value,minPurchase:Number(document.querySelector('#promotionMinimum').value),startsAt:start?new Date(start).toISOString():'',expiresAt:end?new Date(end).toISOString():'',isActive:document.querySelector('#promotionActive').checked};button.disabled=true;button.textContent='Menyimpan…';try{await api(id?`/api/promotions/${id}`:'/api/promotions',{method:id?'PATCH':'POST',body:JSON.stringify(payload)});promotionDialog.close();toast(id?'Voucher berhasil diperbarui':'Voucher berhasil dibuat');await loadPromotions()}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Simpan voucher'}});
